import { TtlCache } from '/work/src/cache.mjs';
import { Store } from '/work/src/store.mjs';
import { createApi } from '/work/src/api.mjs';

let now = 0;
const cache = new TtlCache({ ttlMs: 1000, now: () => now });
const store = new Store();
const api = createApi({ store, cache });

// Test 1: Cache miss, read from store
const user1 = { id: '1', email: 'test@example.com', name: 'Test User' };
store.put('1', user1);
const result1 = api.getUser('1');
console.log('Test 1 - Cache miss:', result1.id === '1' && result1.email === 'test@example.com');
console.log('  Store reads before:', store.reads);

// Test 2: Cache hit
const result2 = api.getUser('1');
console.log('Test 2 - Cache hit (no store read):', store.reads === 1);

// Test 3: Mutation doesn't affect cache
result2.name = 'Modified';
const result3 = api.getUser('1');
console.log('Test 3 - Mutations don\'t affect cache:', result3.name === 'Test User');

// Test 4: Cache expiration
now = 1001;
const result4 = api.getUser('1');
console.log('Test 4 - Cache expired, re-read from store:', store.reads === 2);

// Test 5: saveUser invalidates cache
now = 0;
const user2 = { id: '2', email: 'test2@example.com', name: 'Test User 2' };
api.saveUser(user2);
console.log('Test 5 - saveUser stored:', store.reads === 2); // Still 2, didn't read
const result5 = api.getUser('2');
console.log('  Retrieved cached user:', result5.id === '2');

// Test 6: deleteUser invalidates cache
api.deleteUser('2');
const result6 = api.getUser('2');
console.log('Test 6 - deleteUser invalidated cache:', result6 === undefined);

// Test 7: importUsers
const users = [{ id: '3', email: 'test3@example.com', name: 'User 3' }];
api.importUsers(users);
const result7 = api.getUser('3');
console.log('Test 7 - importUsers cached:', result7.id === '3');

// Test 8: deleteByDomain
const users2 = [
  { id: '4', email: 'user4@example.com', name: 'User 4' },
  { id: '5', email: 'user5@other.com', name: 'User 5' }
];
api.importUsers(users2);
const removed = api.deleteByDomain('example.com');
console.log('Test 8 - deleteByDomain removed user 4:', removed.includes('4'));
const result8 = api.getUser('4');
console.log('  Cache invalidated:', result8 === undefined);

// Test 9: listUsers returns copies
const all = api.listUsers();
all[0].name = 'Mutated';
const refetch = api.getUser(all[0].id);
