1	export class TtlCache {
2	  #entries = new Map();
3	  #ttlMs;
4	  #now;
5	
6	  constructor({ ttlMs, now = Date.now }) {
7	    this.#ttlMs = ttlMs;
8	    this.#now = now;
9	  }
10	
11	  set(key, value) {
12	    const copy = structuredClone(value);
13	    this.#entries.set(key, { value: copy, expiresAt: this.#now() + this.#ttlMs });
14	  }
15	
16	  get(key) {
17	    const entry = this.#entries.get(key);
18	    if (!entry) return undefined;
19	    if (this.#now() >= entry.expiresAt) {
20	      this.#entries.delete(key);
21	      return undefined;
22	    }
23	    return structuredClone(entry.value);
24	  }
25	
26	  delete(key) {
27	    this.#entries.delete(key);
28	  }
29	
30	  clear() {
31	    this.#entries.clear();
32	  }
33	
34	  has(key) {
35	    return this.get(key) !== undefined;
36	  }
37	
38	  get size() {
39	    let count = 0;
40	    for (const [key, entry] of this.#entries) {
41	      if (this.#now() < entry.expiresAt) {
42	        count++;
43	      } else {
44	        this.#entries.delete(key);
45	      }
46	    }
47	    return count;
48	  }
49	}
50

1	export function createApi({ store, cache }) {
2	  return {
3	    getUser(id) {
4	      const cached = cache.get(`user:${id}`);
5	      if (cached !== undefined) {
6	        return cached;
7	      }
8	      const user = store.get(id);
9	      if (user === undefined) {
10	        return undefined;
11	      }
12	      cache.set(`user:${id}`, user);
13	      return structuredClone(user);
14	    },
15	
16	    saveUser(user) {
17	      const copy = structuredClone(user);
18	      store.put(user.id, copy);
19	      cache.set(`user:${user.id}`, copy);
20	      return structuredClone(copy);
21	    },
22	
23	    deleteUser(id) {
24	      cache.delete(`user:${id}`);
25	      return store.remove(id);
26	    },
27	
28	    importUsers(users) {
29	      const copies = users.map(u => structuredClone(u));
30	      store.putMany(copies);
31	      for (const copy of copies) {
32	        cache.set(`user:${copy.id}`, copy);
33	      }
34	    },
35	
36	    deleteByDomain(domain) {
37	      const removed = store.removeWhere((user) => user.email.endsWith(`@${domain}`));
38	      for (const id of removed) {
39	        cache.delete(`user:${id}`);
40	      }
41	      return removed;
42	    },
43	
44	    listUsers() {
45	      return store.all().map(u => structuredClone(u));
46	    },
47	  };
48	}
